import{_ as o,o as a,c as t,a2 as i}from"./chunks/framework.BN2sqjC1.js";const u=JSON.parse('{"title":"ADR-0001 — Consegna degli URL memobrain:// per sistema operativo (SPIKE-01)","description":"","frontmatter":{},"headers":[],"relativePath":"adr/0001-url-scheme-delivery.md","filePath":"adr/0001-url-scheme-delivery.md"}'),n={name:"adr/0001-url-scheme-delivery.md"};function c(r,e,s,d,l,p){return a(),t("div",null,[...e[0]||(e[0]=[i('<h1 id="adr-0001-—-consegna-degli-url-memobrain-per-sistema-operativo-spike-01" tabindex="-1">ADR-0001 — Consegna degli URL <code>memobrain://</code> per sistema operativo (SPIKE-01) <a class="header-anchor" href="#adr-0001-—-consegna-degli-url-memobrain-per-sistema-operativo-spike-01" aria-label="Permalink to &quot;ADR-0001 — Consegna degli URL `memobrain://` per sistema operativo (SPIKE-01)&quot;">​</a></h1><table tabindex="0"><thead><tr><th></th><th></th></tr></thead><tbody><tr><td><strong>Stato</strong></td><td>accettata (verifica manuale su macOS/Windows/Linux in <code>docs/qa/m0-checklist.md</code>)</td></tr><tr><td><strong>Data</strong></td><td>2026-10-23</td></tr><tr><td><strong>Riferimenti spec</strong></td><td>§1.3, §2.2.1 (URI scheme), D-07, D-08</td></tr><tr><td><strong>Devia dallo spec?</strong></td><td>no</td></tr></tbody></table><blockquote><p><strong>Nota (ADR-0051, accettata il 2026-11-20 e recepita in <code>Specifications.md</code> v1.8).</strong> Il client desktop è su Wails <strong>v3.1.0</strong> (dalla 1.4.0), non più su Wails v2 (2.12): su macOS l&#39;URL arriva con l&#39;evento <code>ApplicationLaunchedWithUrl</code> (<code>apps/desktop/internal/shell/url.go</code>), non con <code>Mac.OnUrlOpen</code>; su Windows e Linux resta il single-instance lock con gli argomenti della seconda istanza. Lo schema URL e i metadati degli installer non sono più in <code>wails.json</code> (che non esiste più) ma in <code>apps/desktop/build/project.json</code>; lo schema oggi è <code>clarae://</code> (ADR-0052). Il testo qui sotto è storico e non cambia.</p></blockquote><h2 id="contesto" tabindex="-1">Contesto <a class="header-anchor" href="#contesto" aria-label="Permalink to &quot;Contesto&quot;">​</a></h2><p>Lo scheme <code>memobrain://</code> serve ad aprire note (<code>memobrain://open?vault=…&amp;file=…</code>) e come fallback del redirect OIDC (<code>memobrain://auth/callback</code>). Wails v2 (2.12) consegna l&#39;URL in modo diverso per OS: su macOS tramite <code>Mac.OnUrlOpen</code> (anche ad app già in esecuzione, gestito dal sistema con l&#39;handler di apertura URL); su Windows (solo installer NSIS) e Linux (<code>.desktop</code> con <code>x-scheme-handler</code>) il sistema avvia una <strong>seconda istanza</strong> con l&#39;URL in <code>argv</code>, che il <code>SingleInstanceLock</code> inoltra all&#39;istanza attiva tramite <code>OnSecondInstanceLaunch</code>.</p><h2 id="decisione" tabindex="-1">Decisione <a class="header-anchor" href="#decisione" aria-label="Permalink to &quot;Decisione&quot;">​</a></h2><ul><li><code>main.go</code> registra entrambi i canali: <code>Mac.OnUrlOpen → app.HandleURL</code> e <code>SingleInstanceLock.OnSecondInstanceLaunch → platform.FindSchemeURL(args) → app.HandleURL</code>; la prima istanza controlla anche i propri <code>os.Args</code>.</li><li><code>UniqueId</code> del lock è derivato dalla <strong>directory dati</strong> (<code>platform.InstanceID</code>), così due istanze con <code>--data-dir</code> diversi coesistono (test multi-dispositivo in M2).</li><li>Gli URL ricevuti prima che il frontend sia pronto vengono accodati e consegnati in <code>OnDomReady</code>.</li><li>Il loopback resta il percorso primario del login (D-08); lo scheme è fallback e la sicurezza del callback si basa su PKCE + <code>state</code> tenuti solo in memoria dell&#39;istanza che ha avviato il login.</li></ul><h2 id="alternative-considerate" tabindex="-1">Alternative considerate <a class="header-anchor" href="#alternative-considerate" aria-label="Permalink to &quot;Alternative considerate&quot;">​</a></h2><ul><li><strong>Solo custom scheme</strong> — scartata: registrazione non garantita (AppImage, policy aziendali, Linux senza <code>.desktop</code>).</li><li><strong>Solo loopback</strong> — scartata: alcuni ambienti bloccano i listener locali o Keycloak può rifiutare <code>invalid_redirect_uri</code>.</li></ul><h2 id="conseguenze" tabindex="-1">Conseguenze <a class="header-anchor" href="#conseguenze" aria-label="Permalink to &quot;Conseguenze&quot;">​</a></h2><p>Il comportamento &quot;URL verso app già aperta&quot; va verificato manualmente su ciascun OS (checklist M0); la registrazione dello scheme negli installer è parte di M7-WP3 (NSIS, <code>Info.plist</code> generato da <code>wails.json</code> <code>info.protocols</code>, <code>.desktop</code>).</p>',11)])])}const g=o(n,[["render",c]]);export{u as __pageData,g as default};
